//! Canonical lexical ownership. Only the owned tokenizer can populate tokens;
//! callers cannot pair another document's token spans with arbitrary bytes.
use crate::types::{invalid, limit, stopped};
use crate::*;
use vexel_xml::{StreamStatus, XmlError, XmlToken, XmlTokenStream};
#[derive(Debug)]
pub struct LexicalDocument {
    source: SourceOwner,
    tokens: Vec<XmlToken>,
}
impl LexicalDocument {
    pub fn parse(
        source: SourceOwner,
        max_token_storage_bytes: usize,
        control: &mut dyn WorkControl,
    ) -> Result<Self> {
        control.checkpoint().map_err(stopped)?;
        if source.len() > 1 << 30 {
            return Err(limit(LimitKind::SourceBytes));
        }
        let maximum = max_token_storage_bytes.min(256 * 1024 * 1024);
        if maximum < std::mem::size_of::<XmlToken>() {
            return Err(limit(LimitKind::TokenBytes));
        }
        let mut stream = XmlTokenStream::new(&source, maximum).map_err(|_| Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        })?;
        loop {
            let mut reason = None;
            let status = {
                let mut cancel = || match control.charge(WorkKind::SourceRead, 1) {
                    Ok(()) => false,
                    Err(stop) => {
                        reason.get_or_insert(stop);
                        true
                    }
                };
                stream.step_with_cancel(256, &mut cancel)
            };
            if let Some(stop) = reason {
                return Err(stopped(stop));
            }
            match status {
                StreamStatus::Ok => {}
                StreamStatus::Complete => break,
                StreamStatus::Canceled => return Err(stopped(Stop::Canceled)),
                StreamStatus::Failed => {
                    let d = stream.result().diagnostic;
                    return Err(Diagnostic {
                        kind: if d.category == XmlError::OutputExhausted {
                            ErrorKind::Limit(LimitKind::TokenBytes)
                        } else {
                            ErrorKind::Xml(d.category)
                        },
                        offset: d.offset,
                    });
                }
            }
        }
        let tokens = stream.take().ok_or_else(|| invalid(0))?;
        drop(stream);
        Ok(Self { source, tokens })
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn source(&self) -> &[u8] {
        &self.source
    }
    pub fn tokens(&self) -> &[XmlToken] {
        &self.tokens
    }
    pub fn token_storage_bytes(&self) -> Result<usize> {
        crate::memory::bytes(&self.tokens)
    }
}
use std::sync::{
    Arc,
    atomic::{AtomicBool, Ordering},
};
use vexel_scene::{ErrorKind, Limits, SceneBuilder, Stop, Viewport, WorkControl, WorkKind};
use vexel_svg_animation::parse_owned;

struct Control {
    canceled: AtomicBool,
    work: u64,
    limit: u64,
}
impl Control {
    fn new(limit: u64) -> Self {
        Self {
            canceled: AtomicBool::new(false),
            work: 0,
            limit,
        }
    }
}
impl WorkControl for Control {
    fn charge(&mut self, _: WorkKind, units: u64) -> Result<(), Stop> {
        if self.canceled.load(Ordering::Acquire) {
            return Err(Stop::Canceled);
        }
        let next = self.work.checked_add(units).ok_or(Stop::Overflow)?;
        if next > self.limit {
            return Err(Stop::Limit);
        }
        self.work = next;
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        if self.canceled.load(Ordering::Acquire) {
            Err(Stop::Canceled)
        } else {
            Ok(())
        }
    }
}

fn graph() -> vexel_scene::SceneGraph {
    let source = Arc::new(b"<svg/>".to_vec());
    let animation = parse_owned(&source, &[]).unwrap();
    let viewport = Viewport {
        width: 4,
        height: 4,
        view_x: 0.0,
        view_y: 0.0,
        view_width: 4.0,
        view_height: 4.0,
        aspect: Default::default(),
    };
    SceneBuilder::new(source, animation, 1, viewport, Limits::default())
        .unwrap()
        .freeze()
        .unwrap()
}

#[test]
fn empty_owned_scene_evaluates_without_copying_or_losing_child_lookup() {
    let graph = graph();
    let mut control = Control::new(u64::MAX);
    let frame = vexel_svg_animation_frame::evaluate_frame(graph.root(), 0.0, &mut control).unwrap();
    let view = frame.view();
    assert!(view.shapes.is_empty());
    assert!(view.scene(view.id).is_some());
    assert_eq!(frame.memory_stats().live_bytes, 0);
}

#[test]
fn invalid_time_and_cancellation_are_reported_without_a_frame() {
    let graph = graph();
    let mut control = Control::new(u64::MAX);
    assert_eq!(
        vexel_svg_animation_frame::evaluate_frame(graph.root(), f64::NAN, &mut control)
            .unwrap_err()
            .kind,
        ErrorKind::InvalidArgument,
    );
    control.canceled.store(true, Ordering::Release);
    assert_eq!(
        vexel_svg_animation_frame::evaluate_frame(graph.root(), 0.0, &mut control)
            .unwrap_err()
            .kind,
        ErrorKind::Canceled,
    );
}

