            let t = (x * 0.017453292519943295769).tan();
            if !t.is_finite() || t.abs() > 1e6 {
                return None;
            }
            if track.transform_type == TransformType::SkewX {
                m.c = t
            } else {
                m.b = t
            }
        }
    }
