fn shape_has_node(
    shape: &Shape,
    transforms: &[TransformFrame],
    target: TransformId,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<bool> {
    let mut node = shape.source.transform_node;
    let mut depth = 0;
